function request(revision=1){return {mode:'full',instruction:'Use my current source answers to propose a concise, factual summary addition for review. Keep scope and qualifications. Do not apply changes.',targetRole:'',cvVersionId:'synthetic-source-cv-1',cvTitle:'Sara Example',selectedBlockIds:[],blocks:structuredClone(blocks),language:'en',sourcesSchemaVersion:'1.0',sourceContext:{contextRevision:'synthetic-context-'+revision,roundId:'synthetic-round-1',jobContext:structuredClone(jobContext),questions:questions.map((question,i)=>({id:'q'+(i+1),question,signalRefs:[{field:'topPriorities',index:i}],status:['recorded','recorded','skipped','no','unknown'][i]})),answers:[{id:'a1',questionId:'q1',revision:1,text:'I coordinated one product release with two developers.'},{id:'a2',questionId:'q2',revision,text:revision===1?first:corrected}]}};}
function output(r){return {updates:[{blockId:'summary-1',additions:r.sourceContext.answers.map(a=>({text:a.id==='a1'?'Coordinated a product release with two developers.':a.revision===1?'Designed and facilitated two internal AI workshops for design colleagues.':'Prepared slides for two internal AI workshops facilitated by a colleague.',answerId:a.id,answerRevision:a.revision,sourceQuote:a.id==='a1'?a.text:a.text.split('. I have not')[0]+'.'}))}]};}
